import{_ as t,o as i,c as a,ao as s}from"./chunks/framework.CWHsw1fv.js";const g=JSON.parse('{"title":"Choosing an algorithm","description":"","frontmatter":{},"headers":[],"relativePath":"algorithms.md","filePath":"algorithms.md","lastUpdated":null}'),o={name:"algorithms.md"};function r(n,e,d,l,h,c){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="Choosing-an-algorithm" tabindex="-1">Choosing an algorithm <a class="header-anchor" href="#Choosing-an-algorithm" aria-label="Permalink to &quot;Choosing an algorithm {#Choosing-an-algorithm}&quot;">​</a></h1><p>Two algorithms solve the same problem. The sixth argument of <a href="/PureOSQP.jl/dev/api#PureOSQP.solve"><code>solve</code></a> and <a href="/PureOSQP.jl/dev/api#PureOSQP.setup"><code>setup</code></a> picks one and holds the settings only that algorithm reads; everything both read is a keyword argument of <a href="/PureOSQP.jl/dev/api#PureOSQP.Options"><code>Options</code></a>.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ws </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> setup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P, q, A, l, u, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">InteriorPoint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); max_iter </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sol </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> solve!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ws)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">algorithm     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># InteriorPoint{Float64, Float64, Float64, Int64}: parameters in the solve&#39;s element type</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">options       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Options{Float64}: max_iter, the tolerances, linsys, polishing, …</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">update_settings!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ws; eps_abs </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1e-10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)                    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># change an option</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">update_settings!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ws, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">InteriorPoint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(reg_primal </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1e-6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># replace the algorithm parameters</span></span></code></pre></div><p>The keyword arguments are the fields of <a href="/PureOSQP.jl/dev/api#PureOSQP.Options"><code>Options</code></a>. The two methods default some of them differently — <code>max_iter</code> is <code>4000</code> for <code>OperatorSplitting</code> and <code>100</code> for <code>InteriorPoint</code>, and the tolerances <code>1e-3</code> and <code>1e-8</code> — and <a href="/PureOSQP.jl/dev/api#PureOSQP.default_options"><code>default_options</code></a> shows the full set for either. A value you pass is always used as given. A setting passed in the wrong place throws, naming where it belongs:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">InteriorPoint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(rho </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)                           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># MethodError: rho is not an InteriorPoint parameter</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">solve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P, q, A, l, u, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">InteriorPoint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); rho </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ArgumentError: rho is a parameter of OperatorSplitting</span></span></code></pre></div><h2 id="Accuracy-and-iteration-count" tabindex="-1">Accuracy and iteration count <a class="header-anchor" href="#Accuracy-and-iteration-count" aria-label="Permalink to &quot;Accuracy and iteration count {#Accuracy-and-iteration-count}&quot;">​</a></h2><p><a href="/PureOSQP.jl/dev/api#PureOSQP.OperatorSplitting"><code>OperatorSplitting</code></a> is OSQP&#39;s ADMM iteration: many cheap iterations sharing one factorization. <a href="/PureOSQP.jl/dev/api#PureOSQP.InteriorPoint"><code>InteriorPoint</code></a> is a Mehrotra predictor–corrector method: a few iterations, each factoring a new Newton system.</p><p><code>bench/ipm_vs_clarabel.jl</code> runs both on the smallest instance of each OSQP suite problem class, <code>InteriorPoint</code> at <code>eps_abs = eps_rel = 1e-8</code> and <code>OperatorSplitting</code> at <code>1e-6</code>, the tightest tolerance ADMM reaches in a modest iteration count on these problems (<code>bench/results/ipm_vs_clarabel.json</code>):</p><table tabindex="0"><thead><tr><th style="text-align:right;">class</th><th style="text-align:right;">ADMM iterations (<code>1e-6</code>)</th><th style="text-align:right;">IPM iterations (<code>1e-8</code>)</th></tr></thead><tbody><tr><td style="text-align:right;">Random QP</td><td style="text-align:right;">200</td><td style="text-align:right;">9</td></tr><tr><td style="text-align:right;">Eq QP</td><td style="text-align:right;">50</td><td style="text-align:right;">2</td></tr><tr><td style="text-align:right;">Portfolio</td><td style="text-align:right;">125</td><td style="text-align:right;">10</td></tr><tr><td style="text-align:right;">Lasso</td><td style="text-align:right;">100</td><td style="text-align:right;">6</td></tr><tr><td style="text-align:right;">SVM</td><td style="text-align:right;">375</td><td style="text-align:right;">9</td></tr><tr><td style="text-align:right;">Huber</td><td style="text-align:right;">125</td><td style="text-align:right;">9</td></tr><tr><td style="text-align:right;">Control</td><td style="text-align:right;">50</td><td style="text-align:right;">7</td></tr></tbody></table><p><code>InteriorPoint</code> reaches a tighter tolerance in 2 to 10 outer iterations; <code>OperatorSplitting</code> takes 50 to 375 at a looser one on the same problems. The gap is not just a fixed offset: the benchmark suite&#39;s full-size problems, run through <a href="/PureOSQP.jl/dev/benchmarks#The-OSQP-benchmark-suite"><code>bench/osqp_suite.jl</code></a> at <code>eps_abs = eps_rel = 1e-5</code> and through <a href="/PureOSQP.jl/dev/benchmarks#The-ρ-schedule"><code>bench/rho_schedule.jl</code></a> at <code>1e-6</code>, take more ADMM iterations at the tighter tolerance on every class that changes at all — Random QP 925 → 1225, Portfolio 450 → 600, Lasso 100 → 125, SVM 300 → 325, Control 325 → 450. <code>InteriorPoint</code>&#39;s iteration count is set by Newton&#39;s method converging locally, which is far less sensitive to how tight the tolerance is; <code>OperatorSplitting</code>&#39;s is a first-order method&#39;s, which is not.</p><p>This is not a claim that <code>InteriorPoint</code> is always faster: each of its iterations costs a factorization, where ADMM&#39;s iterations only apply the one it already has, so the crossover depends on the problem. <a href="/PureOSQP.jl/dev/benchmarks#The-interior-point-method-against-Clarabel">Benchmarks</a> has the times, not just the iteration counts.</p><h2 id="Re-solving-a-sequence" tabindex="-1">Re-solving a sequence <a class="header-anchor" href="#Re-solving-a-sequence" aria-label="Permalink to &quot;Re-solving a sequence {#Re-solving-a-sequence}&quot;">​</a></h2><p>Both algorithms accept <a href="/PureOSQP.jl/dev/api#PureOSQP.update!"><code>update!</code></a>, <a href="/PureOSQP.jl/dev/api#PureOSQP.warm_start!"><code>warm_start!</code></a>, <a href="/PureOSQP.jl/dev/api#PureOSQP.cold_start!"><code>cold_start!</code></a> and <a href="/PureOSQP.jl/dev/api#PureOSQP.update_settings!"><code>update_settings!</code></a>, and both start a re-solve from the previous point when <code>warm_starting = true</code> (the default).</p><p><strong><code>OperatorSplitting</code> can skip the factorization entirely.</strong> Updating <code>q</code> alone never refactorizes; updating <code>l</code> or <code>u</code> only does if a row moves between equality, inequality and free; <code>P</code> or <code>A</code> always does. The Model Predictive Control loop in <a href="/PureOSQP.jl/dev/examples#Model-predictive-control">Examples</a> is built on this: fifteen closed-loop solves, one factorization, because only the initial-state bounds move and none of them cross a class. Each solve is then also short, because it starts from the previous step&#39;s iterates — this is what the warm start buys under ADMM: fewer iterations on top of no refactorization.</p><p><strong><code>InteriorPoint</code> refactors every outer iteration regardless of <code>update!</code>.</strong> Every iteration solves a fresh Newton system at that iteration&#39;s row weights, so there is no factorization for <code>update!</code> to preserve — it saves the equilibration and the buffers, not a solve. <code>warm_start!</code> still seeds the first iterate from a point you supply, and a re-solve takes at most as many outer iterations as a cold one (checked in <code>test/ipm_tests.jl</code>), but there is little to save: the count is already 2 to 10 at the default tolerance, so a warm start shortens an already short run rather than replacing hundreds of iterations with dozens.</p><h2 id="What-each-algorithm-throws-on" tabindex="-1">What each algorithm throws on <a class="header-anchor" href="#What-each-algorithm-throws-on" aria-label="Permalink to &quot;What each algorithm throws on {#What-each-algorithm-throws-on}&quot;">​</a></h2><p>Neither algorithm restricts the matrix types in <a href="./matrices">Matrix types</a> or <a href="/PureOSQP.jl/dev/operators#Structured-operators">Structured operators</a> beyond what <code>linsys</code> demands. The differences are in what a caller-supplied operator needs, and in which <code>linsys</code> backends each algorithm accepts.</p><table tabindex="0"><thead><tr><th style="text-align:right;"></th><th style="text-align:right;"><code>OperatorSplitting</code></th><th style="text-align:right;"><code>InteriorPoint</code></th></tr></thead><tbody><tr><td style="text-align:right;">matrix-free operators (<code>linsys = :indirect</code>)</td><td style="text-align:right;">works with the built-in Jacobi preconditioner, or none</td><td style="text-align:right;">needs <code>linsys = :indirect</code>, a <strong>caller-supplied</strong> preconditioner, and <code>scaling = 0</code>; passing the built-in preconditioners or equilibration throws, naming the remedy (<a href="/PureOSQP.jl/dev/operators#Operators-under-the-interior-point-method">Operators under the interior-point method</a>)</td></tr><tr><td style="text-align:right;"><code>linsys = :kronecker</code></td><td style="text-align:right;">works</td><td style="text-align:right;">throws: the Kronecker backend needs one weight for every row, and the interior-point method&#39;s weights are per-row</td></tr><tr><td style="text-align:right;"><code>linsys = :lowrank</code></td><td style="text-align:right;">works</td><td style="text-align:right;">throws: the Woodbury solve misses the tolerance on linear programs (<a href="/PureOSQP.jl/dev/algorithm#Backends-under-the-interior-point-method">Algorithm</a>)</td></tr></tbody></table><p>The reason <code>InteriorPoint</code> needs a caller&#39;s own preconditioner on an operator is measured, not assumed: its row weights reach <code>1/reg_dual</code> (<code>1e8</code> by default) on equality and active rows and change every outer iteration, so a fixed diagonal preconditioner does not keep conjugate gradients within budget the way it does under ADMM&#39;s fixed <code>ρ</code>. <code>bench/ipm_matrixfree.jl</code> measures this on 24 dense planted instances with a lagged Cholesky preconditioner the caller supplies, refreshed every third outer iteration: all 24 solve at <code>eps = 1e-6</code> with a referee residual of at most <code>7.9e-7</code>, in the same outer iterations as the dense full-KKT factorization (<code>bench/results/ipm_matrixfree.json</code>). One sparse instance with a limited-memory incomplete <code>LDLᵀ</code> preconditioner fails instead — a preconditioner has to keep the inner iteration count bounded as the weights spread, and not every cheap one does.</p><h2 id="Polishing,-derivatives-and-infeasibility" tabindex="-1">Polishing, derivatives and infeasibility <a class="header-anchor" href="#Polishing,-derivatives-and-infeasibility" aria-label="Permalink to &quot;Polishing, derivatives and infeasibility {#Polishing,-derivatives-and-infeasibility}&quot;">​</a></h2><p><strong>Polishing</strong> runs the same way under both: <code>polishing = true</code> guesses the active set from the iterate, solves the resulting equality-constrained QP with <code>bunchkaufman!</code> and three steps of iterative refinement, and replaces the answer only if both residuals improve. The <code>polishing</code>, <code>polish_refine_iter</code> and <code>delta</code> options apply to either algorithm.</p><p><strong>Derivatives require polishing under <code>InteriorPoint</code>, not under <code>OperatorSplitting</code>.</strong> <a href="/PureOSQP.jl/dev/api#PureOSQP.adjoint_derivative"><code>adjoint_derivative</code></a> and <a href="/PureOSQP.jl/dev/api#PureOSQP.forward_derivative"><code>forward_derivative</code></a> read the active set from a row&#39;s multiplier being far from zero. ADMM projects its multipliers onto the feasible box directly, so an inactive row&#39;s multiplier is already at (or near) zero and there is nothing extra to check. An interior-point solution holds an inactive row&#39;s multiplier at the barrier parameter <code>μ_final</code> instead, which the active-set test cannot tell apart from a genuinely active one — so taking a derivative from an unpolished <code>InteriorPointWorkspace</code> throws, asking for <code>polishing = true</code> first, and polishing is what brings that multiplier down before the derivative is taken.</p><p><strong>Infeasibility certificates are the same test under both.</strong> <code>InteriorPoint</code> does not implement its own primal- and dual-infeasibility check; it reuses ADMM&#39;s certificate test, applied to its own last step and its normalized iterate. Both report <code>PRIMAL_INFEASIBLE</code> and <code>DUAL_INFEASIBLE</code> (and their <code>*_INACCURATE</code> variants) with a certificate in <code>Solution.prim_inf_cert</code> or <code>Solution.dual_inf_cert</code>.</p><p><strong>What <code>Solution</code> carries differs in what reads zero.</strong> The struct is shared, so every field exists under both algorithms, but <code>rho_estimate</code>, <code>rho_updates</code>, <code>accel_declined</code>, <code>primdual_int</code> and <code>primdual_int_log</code> are always zero under <code>InteriorPoint</code> — there is no <code>ρ</code>, no accelerator and no primal-dual integral to report. <code>cg_iters</code> is nonzero for either algorithm only under <code>linsys = :indirect</code>. <code>NUMERICAL_ERROR</code> is a status only <code>InteriorPoint</code> returns — a stalled Newton system, a non-finite residual, or conjugate gradients missing too many solves in a row; ADMM never reports it.</p><h2 id="Summary" tabindex="-1">Summary <a class="header-anchor" href="#Summary" aria-label="Permalink to &quot;Summary {#Summary}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;"></th><th style="text-align:right;"><code>OperatorSplitting</code> (default)</th><th style="text-align:right;"><code>InteriorPoint</code></th></tr></thead><tbody><tr><td style="text-align:right;">iteration cost</td><td style="text-align:right;">many cheap iterations, one factorization reused until <code>ρ</code> changes</td><td style="text-align:right;">a few iterations, a fresh factorization each</td></tr><tr><td style="text-align:right;">default tolerance</td><td style="text-align:right;"><code>1e-3</code></td><td style="text-align:right;"><code>1e-8</code></td></tr><tr><td style="text-align:right;"><code>update!</code></td><td style="text-align:right;">can skip refactorization entirely (<code>q</code>-only updates always do)</td><td style="text-align:right;">refactorizes every outer iteration regardless</td></tr><tr><td style="text-align:right;">matrix-free operators</td><td style="text-align:right;">no restriction</td><td style="text-align:right;">needs a caller-supplied preconditioner and <code>scaling = 0</code></td></tr><tr><td style="text-align:right;"><code>linsys = :kronecker</code>, <code>:lowrank</code></td><td style="text-align:right;">works</td><td style="text-align:right;">throws</td></tr><tr><td style="text-align:right;">derivatives</td><td style="text-align:right;">ready from the iterate as it stands</td><td style="text-align:right;">require <code>polishing = true</code> first</td></tr><tr><td style="text-align:right;">infeasibility certificates</td><td style="text-align:right;">yes</td><td style="text-align:right;">yes, through the same test</td></tr></tbody></table><p>Reach for <code>InteriorPoint</code> when the tolerance you need is tighter than ADMM reaches in a modest iteration count, or when you are solving once rather than in a loop that reuses a factorization. Reach for <code>OperatorSplitting</code> for repeated solves through <code>update!</code> and for matrix-free operators without a preconditioner of your own.</p><p>Timing tables, not just iteration counts, are in <a href="/PureOSQP.jl/dev/benchmarks#The-interior-point-method-against-Clarabel">Benchmarks</a> and the benchmark suite tables above it; this page states which algorithm qualifies for a given problem, not how many milliseconds it takes.</p>`,28)])])}const u=t(o,[["render",r]]);export{g as __pageData,u as default};
